import{_ as o,o as t,c as d,ae as a}from"./chunks/framework.BX6FPmO9.js";const u=JSON.parse('{"title":"Design System","description":"","frontmatter":{},"headers":[],"relativePath":"DESIGN_SYSTEM.md","filePath":"DESIGN_SYSTEM.md"}'),c={name:"DESIGN_SYSTEM.md"};function i(s,e,r,n,l,p){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="design-system" tabindex="-1">Design System <a class="header-anchor" href="#design-system" aria-label="Permalink to &quot;Design System&quot;">​</a></h1><p><strong>類型</strong>：reference | <strong>權重</strong>：2</p><p>這份設計系統文件用來維持 UI 一致性與可維護性；專案朝向 <strong>半自動化 UI</strong> 逐漸建立 design system（見 <a href="./architecture/design-system.html">docs/architecture/design-system.md</a>）。 本專案採用 shadcn/ui 作為元件基礎，確保可維護且可客製。</p><h2 id="token-source-of-truth" tabindex="-1">Token Source of Truth <a class="header-anchor" href="#token-source-of-truth" aria-label="Permalink to &quot;Token Source of Truth&quot;">​</a></h2><ul><li><strong>SSOT</strong>：<a href="https://www.npmjs.com/package/@is_tess/tokens" target="_blank" rel="noreferrer">@is_tess/tokens</a>（explore-design-sdk application map <code>portal</code>）。</li><li>消費鏈：SDK <code>pnpm tokens:css</code> → publish <code>@is_tess/tokens</code> → portal <code>app/styles/tokens.portal.css</code> <strong>只做 npm CSS <code>@import</code></strong>（不再 vendor 一份色值）→ <code>app/tailwind.css</code> 橋接 shadcn 變數 ← SDK semantic → <code>tailwind.config.ts</code> 以 <code>var(--x)</code> 消費。</li><li><strong>改色請改 SDK 的 <code>portal.map.json</code></strong> 後重新 publish；不要在 portal 內手改 token 色值；<code>data-app=&quot;portal&quot;</code> 掛在 <code>app/root.tsx</code> 的 <code>&lt;html&gt;</code>。</li><li>Dark／主題 CSS：<code>@is_tess/tokens/css/portal*.css</code>（含 yamabuki／matcha-fuji／wakakusa／untitled）。</li><li>UI 元件：<code>app/components/ui/*</code> re-export <code>@is_tess/components</code>。</li><li>設計稿與 token 同步流程見 <a href="./architecture/figma-mcp.html">docs/architecture/figma-mcp.md</a>。</li></ul><h2 id="design-tokens" tabindex="-1">Design Tokens <a class="header-anchor" href="#design-tokens" aria-label="Permalink to &quot;Design Tokens&quot;">​</a></h2><ul><li>Semantic（SDK）：<code>surface.canvas/elevated/muted</code>、<code>text.primary/secondary/inverse</code>、<code>accent.brand</code>、<code>border.primary</code>、<code>status.danger(-contrast)</code>、<code>radius.base</code>、<code>motion.*</code></li><li>Tailwind 消費：<code>bg-background</code>, <code>text-foreground</code>, <code>text-muted-foreground</code>, <code>border-border</code>, <code>border-input</code></li><li>Brand scale：<code>brand-50</code> ~ <code>brand-900</code> = SDK primitives <code>colors.ai</code>（藍/Japan Blue scale；config 內為 synced 硬編碼，發布後改產出）</li></ul><h2 id="色盤-—-多主題系統-2026-07-08-ssot-sdk-docs-palette-md" tabindex="-1">色盤 — 多主題系統（2026-07-08，SSOT：SDK docs/PALETTE.md） <a class="header-anchor" href="#色盤-—-多主題系統-2026-07-08-ssot-sdk-docs-palette-md" aria-label="Permalink to &quot;色盤 — 多主題系統（2026-07-08，SSOT：SDK docs/PALETTE.md）&quot;">​</a></h2><p>三套可切換主題，全部由 explore-design-sdk theme maps 供應（每套 light+dark）：</p><table tabindex="0"><thead><tr><th>主題</th><th>data-theme</th><th>種子</th></tr></thead><tbody><tr><td>蜜蝋 Mitsurou（預設）</td><td>（無屬性）</td><td>蜂蜜黃 <code>#FFDA76</code> × 蜜蠟白底 <code>#FAF8F5</code> × 焦糖 <code>#DAA277</code></td></tr><tr><td>山吹 Yamabuki</td><td><code>yamabuki</code></td><td>金 <code>#F8B500</code> × 中性灰底 × 橙紐 <code>#C9703D</code></td></tr><tr><td>抹茶と藤 Matcha-Fuji</td><td><code>matcha-fuji</code></td><td>抹茶 <code>#CBD892</code> × 亞麻底 × 薰衣草 <code>#E1C2FF</code></td></tr></tbody></table><p>切換：<code>&lt;html&gt;</code> 的 <code>data-theme</code> + <code>.dark</code> class（ThemeSwitcher 元件，localStorage 記憶，root.tsx init script 防 FOUC）。<strong>portal 不自持任何色值</strong>——bridge 只做 shadcn 變數 ← SDK semantic 變數的參照，主題與 dark 全由 <code>@is_tess/tokens/css/portal*.css</code> 承接。新增 semantic：<code>surface.highlight</code>（chips/badge）、<code>accent.strong</code>（連結/小字級 accent）。改色一律改 SDK 對應 theme map。紙質感 noise（opacity 0.04）沿用。</p><h2 id="元件-canonical-s2-起" tabindex="-1">元件 Canonical（S2 起） <a class="header-anchor" href="#元件-canonical-s2-起" aria-label="Permalink to &quot;元件 Canonical（S2 起）&quot;">​</a></h2><p>基礎元件 canonical 在 <strong>explore-design-sdk <code>packages/components</code></strong>（<code>@is_tess/components</code>）；本 repo <code>app/components/ui/*</code> 為 vendored 副本（見該目錄 README），發布 npm 後改 import。</p><h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to &quot;Core Components&quot;">​</a></h2><ul><li><code>Button</code> (<code>default</code> | <code>secondary</code> | <code>outline</code> | <code>ghost</code> | <code>lui</code>)</li><li><code>Input</code> / <code>Textarea</code></li><li><code>Card</code> + <code>CardHeader</code> + <code>CardContent</code></li><li><code>Badge</code></li><li><code>Alert</code></li><li><code>Container</code></li></ul><h2 id="component-layers" tabindex="-1">Component Layers <a class="header-anchor" href="#component-layers" aria-label="Permalink to &quot;Component Layers&quot;">​</a></h2><ul><li><code>app/components/ui/*</code>: 最小顆粒的設計系統元件（以 cva 定義 variants）</li><li><code>app/components/shared/lui/*</code>: LUI 專用語義元件（例如 <code>ChatBubble</code>）</li><li><code>app/components/shared/chat/*</code>: 複合元件（組合 UI + LUI 元件）</li><li><code>app/components/app/*</code>: 應用基礎元件（例如 ErrorBoundary）</li></ul><h2 id="usage-guidelines" tabindex="-1">Usage Guidelines <a class="header-anchor" href="#usage-guidelines" aria-label="Permalink to &quot;Usage Guidelines&quot;">​</a></h2><ul><li>所有頁面以 <code>Container</code> 作為最大寬度約束。</li><li>大區塊使用 <code>Card</code> 以統一陰影與邊界。</li><li>強調行動使用 <code>Button</code>，避免自建按鈕樣式。</li><li>輕量提示使用 <code>Alert</code>，不要直接用裸 <code>div</code>。</li><li>避免在頁面內直接改 class，改用 <code>variant</code> API。</li></ul><h2 id="ui-review-checklist-2026-07-08-起" tabindex="-1">UI Review Checklist（2026-07-08 起） <a class="header-anchor" href="#ui-review-checklist-2026-07-08-起" aria-label="Permalink to &quot;UI Review Checklist（2026-07-08 起）&quot;">​</a></h2><p>所有 UI PR 依 <a href="./product/ui-review-checklist.html">docs/product/ui-review-checklist.md</a> 自查（surface 分區 + 通用/加驗段）。評估與取捨脈絡見 <a href="./product/visual-quality-plan.html">docs/product/visual-quality-plan.md</a>。</p><h2 id="typography-spacing-tokens-s2-6-2026-07-08" tabindex="-1">Typography / Spacing Tokens（S2.6，2026-07-08） <a class="header-anchor" href="#typography-spacing-tokens-s2-6-2026-07-08" aria-label="Permalink to &quot;Typography / Spacing Tokens（S2.6，2026-07-08）&quot;">​</a></h2><ul><li>Semantic 新增：<code>font.{display,body,mono}</code>、<code>type.{display,title,body,label}.{size,tracking,leading}</code>、<code>weight.{heading,body}</code>、<code>space.{gutter,section,stack,inline,control-x,control-y}</code>——SSOT 同色彩，在 SDK maps。</li><li>風格：portal＝<strong>和紙編輯風</strong>（Petrona/Shippori Mincho display、寬字距、body 行高 1.75）；後台＝Untitled UI 標準（<code>portal-untitled</code> map，Inter、tight、8pt）。此為明文品牌決策（反模板審查的「有意圖」證據）。</li><li>Tailwind 消費：<code>font-display</code>、<code>tracking-title</code>、<code>leading-body</code>、<code>p-gutter</code>、<code>gap-stack</code> 等（tailwind.config 映射）。</li></ul><h2 id="lui-copy-style" tabindex="-1">LUI Copy Style <a class="header-anchor" href="#lui-copy-style" aria-label="Permalink to &quot;LUI Copy Style&quot;">​</a></h2><ul><li>先結論、再依據、最後下一步</li><li>避免過度自信措辭，使用「依目前資訊」「可先嘗試」</li></ul>',25)])])}const m=o(c,[["render",i]]);export{u as __pageData,m as default};
